//! One function, four algebras: the sandwich `exp(t/2 B) x exp(-t/2 B)` rotates a vector in
//! Euclidean 3D, translates a point in projective 3D, boosts an event in spacetime and dilates a
//! point in conformal 3D. The metric comes from the string; `exp` picks cos/sin, 1 + x or
//! cosh/sinh from the sign of `B²`.
//!
//! Run with `cargo run --example four_algebras`.

use seagrass_math::prelude::*;

/// Applies the motion generated by the bivector `generator` for time `t` to `x`.
fn transform<M: Metric>(
    generator: &Multivector<f64, M>,
    x: &Multivector<f64, M>,
    t: f64,
) -> Multivector<f64, M> {
    let versor = (generator * (t / 2.0)).exp();
    let mut out = versor.sandwich(x);
    out.simplify_epsilon(1e-12);
    out
}

/// Parses `generator` and `x`, whose `p,q,r>` prefix picks the algebra, transforms `x`, and
/// prints one row of the table.
fn row<M: Metric>(name: &str, generator: &str, x: &str, t: f64) -> Multivector<f64, M> {
    let generator = Multivector::<f64, M>::from_str(generator).expect("valid generator");
    let x = Multivector::<f64, M>::from_str(x).expect("valid operand");
    let square = (&generator * &generator).scalar();
    let kind = match square {
        s if s < 0.0 => "cos/sin",
        s if s > 0.0 => "cosh/sinh",
        _ => "1 + x",
    };
    let out = transform(&generator, &x, t);
    println!(
        "{name:<20} {:<22} {square:>4}  {kind:<10} {:<28} {out}",
        generator.to_string(),
        x.to_string()
    );
    out
}

fn main() {
    println!(
        "{:<20} {:<22} {:>4}  {:<10} {:<28} result",
        "algebra", "generator B", "B²", "exp", "x"
    );

    // Rotation by 90 degrees in the e12 plane: e1 turns into -e2 (counterclockwise from e2 to e1).
    let rotated = row::<Dyn3>(
        "Euclidean (3,0,0)",
        "3>e12",
        "3>e1",
        std::f64::consts::FRAC_PI_2,
    );
    assert_eq!(rotated.to_string(), "3,0,0>-e2");

    // Translation by 2 along x: the ideal line e14 squares to zero.
    let moved = row::<Dyn4>("Projective (3,0,1)", "3,0,1>e14", "3,0,1>e123", 2.0);
    assert_eq!(moved.to_string(), "3,0,1>e123 - 2e234");

    // A boost with rapidity ln 2 (velocity 0.6c): the time vector e1 picks up an e2 part.
    let boosted = row::<Dyn4>("Spacetime (1,3,0)", "1,3>e12", "1,3>e1", 2f64.ln());
    assert_eq!(boosted.to_string(), "1,3,0>1.25e1 - 0.75e2");
    let interval = (&boosted * &boosted).scalar();
    assert!(
        (interval - 1.0).abs() < 1e-12,
        "boosts preserve the interval"
    );

    // A dilation about the origin: e45 is n_o ^ n_inf up to scale and squares to +1. The point
    // (1, 0, 0) is e1 + n_inf / 2 + n_o = e1 + e5, with n_inf = e4 + e5 and n_o = (e5 - e4) / 2.
    // The result is a multiple of the point (e^-t, 0, 0); dividing by its weight -(x · n_inf)
    // gives the coordinate.
    let dilated = row::<Dyn5>("Conformal (4,1,0)", "4,1>e45", "4,1>e1 + e5", 2f64.ln());
    let weight = dilated.get(BladeIndex::E5) - dilated.get(BladeIndex::E4);
    let x = dilated.get(BladeIndex::E1) / weight;
    assert!(
        (x - 0.5).abs() < 1e-12,
        "dilated by a factor of 1/2: x = {x}"
    );
}
